input.content:
workspace "Order Service" "A service that manages customer orders" {
    model {
        customer = person "Customer" "A customer who places orders"
        paymentProvider = softwareSystem "Payment Provider" "An external service that charges and refunds cards" "External"
        orderService = softwareSystem "Order Service" "Manages the order lifecycle from placement to fulfillment" {
            webApp = container "Web App" "The single-page app customers use to browse and place orders" "React SPA" "Web"
            api = container "API" "The REST API that handles order requests" "Node.js / Express" {
                orderController = component "Order Controller" "Validates and coordinates order placement" "Express Router"
                paymentClient = component "Payment Client" "Talks to the payment provider" "axios"
            }
            database = container "Database" "Stores orders and order items" "PostgreSQL 16" "Database"
            worker = container "Worker" "Processes fulfillment jobs asynchronously" "Node.js / Bull"
        }
        customer -> webApp "Browses the catalogue and places orders through" "HTTPS"
        webApp -> api "Submits orders and queries status via" "HTTPS/JSON"
        api -> database "Persists and reads orders with" "SQL / PostgreSQL 16"
        api -> paymentProvider "Charges cards through" "HTTPS/JSON"
        api -> worker "Enqueues fulfillment jobs to" "AMQP / RabbitMQ"
        worker -> database "Updates order status with" "SQL / PostgreSQL 16"
        worker -> paymentProvider "Refunds failed charges through" "HTTPS/JSON"
        orderController -> paymentClient "Delegates card charging to" "In-process call"
    }
    views {
        systemContext orderService "SystemContext" "System context for the Order Service" {
            include *
            autoLayout
            title "Order Service - System Context"
        }
        container orderService "Containers" "Containers of the Order Service" {
            include *
            autoLayout
            title "Order Service - Containers"
        }
        component api "ApiComponents" "Components of the API container" {
            include *
            autoLayout
            title "Order Service - API Components"
        }
        dynamic orderService "PlaceOrder" "The flow for placing an order" {
            customer -> webApp "places an order through" "HTTPS"
            webApp -> api "submits the order via" "HTTPS/JSON"
            api -> paymentProvider "charges the card through" "HTTPS/JSON"
            api -> database "persists the order with" "SQL / PostgreSQL 16"
            api -> worker "enqueues fulfillment to" "AMQP / RabbitMQ"
            autoLayout
            title "Order Service - Place an Order"
        }
    }
    styles {
        element "Person" {
            shape Person
            background #08427B
            color #ffffff
        }
        element "Software System" {
            background #1168BD
            color #ffffff
        }
        element "External" {
            background #999999
            color #ffffff
        }
        element "Container" {
            background #438DD5
            color #ffffff
        }
        element "Component" {
            background #85BBF0
            color #000000
        }
        element "Database" {
            shape Cylinder
        }
        element "Web" {
            shape WebBrowser
        }
        relationship "Relationship" {
            routing Orthogonal
        }
    }
    configuration {
        scope softwaresystem
    }
}

