        orderService = softwareSystem "Order Service" "Manages the order lifecycle from placement to fulfillment" {
            webApp = container "Web App" "The single-page app customers use to browse and place orders" "React SPA" "Web"
            api = container "API" "The REST API that handles order requests" "Node.js / Express" {
                orderController = component "Order Controller" "Validates and coordinates order placement" "Express Router"
                paymentClient = component "Payment Client" "Talks to the payment provider" "axios"
            }
            database = container "Database" "Stores orders and order items" "PostgreSQL 16" "Database"
            worker = container "Worker" "Processes fulfillment jobs asynchronously" "Node.js / Bull"
        }
        customer -> webApp "Browses the catalogue and places orders through" "HTTPS"
        webApp -> api "Submits orders and queries status via" "HTTPS/JSON"
        api -> database "Persists and reads orders with" "SQL / PostgreSQL 16"
        api -> paymentProvider "Charges cards through" "HTTPS/JSON"
        api -> worker "Enqueues fulfillment jobs to" "AMQP / RabbitMQ"
        worker -> database "Updates order status with" "SQL / PostgreSQL 16"
        worker -> paymentProvider "Refunds failed charges through" "HTTPS/JSON"
        orderController -> paymentClient "Delegates card charging to" "In-process call"
    }
    views {
        systemContext orderService "SystemContext" "System context for the Order Service" {
            include *
            autoLayout
            title "Order Service - System Context"
